#include <boost/multiprecision/cpp_int.hpp>
#include <algorithm>
#include <cstdint>
#include <iostream>
#include <queue>
#include <unordered_map>
#include <utility>
#include <vector>
using boost::multiprecision::cpp_int;
using std::uint64_t;
struct DSU{std::vector<int>p,r;DSU(int n):p(n),r(n,0){for(int i=0;i<n;++i)p[i]=i;}int find(int x){return p[x]==x?x:p[x]=find(p[x]);}void unite(int a,int b){a=find(a);b=find(b);if(a==b)return;if(r[a]<r[b])std::swap(a,b);p[b]=a;if(r[a]==r[b])++r[a];}};
static uint64_t encode(const std::vector<int>&a){uint64_t s=0;for(size_t i=0;i<a.size();++i)s|=(uint64_t(a[i])<<(4*i));return s;}
static std::vector<int>decode(uint64_t s,int w){std::vector<int>a(w);for(int i=0;i<w;++i)a[i]=int((s>>(4*i))&15ULL);return a;}
static std::unordered_map<uint64_t,uint64_t>column_transitions(uint64_t state,int w){std::vector<int>old=decode(state,w);int E=2*w-1;uint64_t masks=1ULL<<E;std::unordered_map<uint64_t,uint64_t>out;out.reserve(1024);for(uint64_t mask=0;mask<masks;++mask){DSU d(2*w);for(int i=0;i<w;++i)for(int j=i+1;j<w;++j)if(old[i]==old[j])d.unite(i,j);for(int j=0;j<w;++j)if((mask>>j)&1ULL)d.unite(j,w+j);for(int j=0;j<w-1;++j)if((mask>>(w+j))&1ULL)d.unite(w+j,w+j+1);std::vector<char>src(2*w,0);for(int i=0;i<w;++i)if(old[i]==0)src[d.find(i)]=1;for(int i=0;i<2*w;++i)if(src[i])src[d.find(i)]=1;bool alive=false;for(int j=0;j<w;++j)if(src[d.find(w+j)]){alive=true;break;}if(!alive)continue;std::unordered_map<int,int>lab;int next=1;std::vector<int>nw(w);for(int j=0;j<w;++j){int root=d.find(w+j);if(src[root])nw[j]=0;else{auto it=lab.find(root);if(it==lab.end())it=lab.emplace(root,next++).first;nw[j]=it->second;}}if(next>16){std::cerr<<"label overflow\n";std::exit(3);}++out[encode(nw)];}return out;}
static cpp_int pow2int(unsigned e){cpp_int x=1;for(unsigned i=0;i<e;++i)x*=2;return x;}static cpp_int pow_int(cpp_int a,unsigned e){cpp_int r=1;while(e){if(e&1)r*=a;e>>=1;if(e)a*=a;}return r;}
struct ExactCross{cpp_int fav,den;size_t final_states;};
static ExactCross exact_crossing(int n){int w=n+1;if(w>8)throw std::runtime_error("checker supports n<=7 with 4-bit labels");std::vector<int>init(w,0);std::unordered_map<uint64_t,cpp_int>dp,ndp;dp.reserve(4096);ndp.reserve(4096);dp[encode(init)]=1;std::unordered_map<uint64_t,std::unordered_map<uint64_t,uint64_t>>cache;for(int col=0;col<2*n;++col){ndp.clear();for(const auto&kv:dp){auto it=cache.find(kv.first);if(it==cache.end())it=cache.emplace(kv.first,column_transitions(kv.first,w)).first;for(const auto&tr:it->second)ndp[tr.first]+=kv.second*tr.second;}dp.swap(ndp);}cpp_int fav=0;for(const auto&kv:dp)fav+=kv.second;cpp_int den=pow2int(unsigned(2*n*(2*n+1)));return{fav,den,dp.size()};}
static cpp_int gcd_cpp(cpp_int a,cpp_int b){if(a<0)a=-a;if(b<0)b=-b;while(b!=0){cpp_int r=a%b;a=b;b=r;}return a;}static bool leq_rat(const cpp_int&an,const cpp_int&ad,const cpp_int&bn,const cpp_int&bd){return an*bd<=bn*ad;}
static uint64_t brute_n1(){std::vector<std::pair<int,int>>edges;auto id=[](int i,int j){return 2*i+j;};for(int i=0;i<2;++i)for(int j=0;j<2;++j)edges.push_back({id(i,j),id(i+1,j)});for(int i=0;i<3;++i)edges.push_back({id(i,0),id(i,1)});uint64_t good=0;for(uint64_t mask=0;mask<(1ULL<<edges.size());++mask){std::vector<std::vector<int>>adj(6);for(size_t e=0;e<edges.size();++e)if((mask>>e)&1ULL){auto[a,b]=edges[e];adj[a].push_back(b);adj[b].push_back(a);}std::queue<int>q;std::vector<char>seen(6,0);for(int j=0;j<2;++j){seen[id(0,j)]=1;q.push(id(0,j));}bool hit=false;while(!q.empty()){int x=q.front();q.pop();if(x==id(2,0)||x==id(2,1)){hit=true;break;}for(int y:adj[x])if(!seen[y]){seen[y]=1;q.push(y);}}if(hit)++good;}return good;}
int main(){std::cout<<"R10 exact frontier-DP certificate\n";std::cout<<"frozen rectangle R=[0,2]x[0,1], delta=1/n, p=1/2, LR crossing\n";uint64_t brute=brute_n1();if(brute!=64){std::cerr<<"n=1 brute mismatch "<<brute<<"\n";return 2;}std::cout<<"n=1 original 7-edge brute force: 64/128 = 1/2 PASS\n";for(int n=1;n<=6;++n){ExactCross ex=exact_crossing(n);cpp_int g=gcd_cpp(ex.fav,ex.den);cpp_int rn=ex.fav/g,rd=ex.den/g;cpp_int lden=pow2int(unsigned(2*n*(n+1)));cpp_int base=pow2int(unsigned(2*n))-1;cpp_int lnum=lden-pow_int(base,unsigned(n+1));cpp_int uden=pow2int(unsigned((n+1)*2*n));cpp_int ubase=pow2int(unsigned(n+1))-1;cpp_int unum=pow_int(ubase,unsigned(2*n));if(!leq_rat(lnum,lden,ex.fav,ex.den)){std::cerr<<"lower bound failed n="<<n<<"\n";return 4;}if(!leq_rat(ex.fav,ex.den,unum,uden)){std::cerr<<"upper bound failed n="<<n<<"\n";return 5;}long double approx=ex.fav.convert_to<long double>()/ex.den.convert_to<long double>();std::cout<<"n="<<n<<" fav="<<ex.fav<<" den="<<ex.den<<" reduced="<<rn<<"/"<<rd<<" p~"<<(double)approx<<" final_states="<<ex.final_states<<" bounds_PASS\n";}std::cout<<"PASS\n";return 0;}
